risk+='''<section class="section section--white"><div class="container section-split"><div class="reveal">'''+e('ACCOUNT STRUCTURE')+'''<h2>Exchange-held assets. Separately managed allocations.</h2><p class="body-copy" style="margin-top:22px">Under the proposed model, investor capital stays in eligible exchange subaccounts owned by the investor, rather than entering a shared Revat trading wallet.</p><p class="body-copy">Revat would execute agreed trading activity through appropriately permissioned connections. This does not make assets self-custodied or immune to exchange risk.</p>'''+button('Read investor model','investors.html','forest')+'''</div><div class="process-diagram reveal">'''+e('SIMPLIFIED CONNECTION')+'''<div class="process-row"><div class="diagram-node"><strong>Investor-owned account</strong><small>Exchange custody</small></div><div class="diagram-arrow">→</div><div class="diagram-node"><strong>Trading-only API</strong><small>Withdrawals disabled</small></div><div class="diagram-arrow">→</div><div class="diagram-node"><strong>Agreed trading & RMS</strong><small>Execution risk remains</small></div></div><p class="notice" style="margin:20px 0 0">Conceptual representation; exchange and permission requirements are subject to final technical verification.</p></div></div></section>
<section class="section"><div class="container">'''+heading('THE RMS','Understand the intended 10% intervention threshold.','The RMS is designed to intervene before losses reach 10% of an individual trading subaccount’s equity. It is not a guaranteed stop, insurance or portfolio-wide limit.')+'''<div class="grid-3">'''+card('01 / SCOPE','Individual subaccount','The target applies to a particular trading subaccount, not automatically to the entire investor portfolio.')+card('02 / EXECUTION','Real conditions matter','Gaps, slippage, liquidity constraints, liquidation and exchange outages can cause losses beyond the intended threshold.')+card('03 / DEFINITION','Final rules are pending','The calculation basis, measurement period, unrealized P&amp;L treatment and intervention behavior must be confirmed.')+'''</div></div></section>
<section class="section section--white"><div class="container">'''+heading('MATERIAL RISKS','Understand what can still go wrong.','The presence of multiple traders, restricted APIs and automated controls does not remove exposure to loss.')+'''<div class="grid-3">'''+card('MARKET','Price and volatility risk','Digital asset prices may move rapidly, affecting both open positions and execution prices.')+card('STRATEGY','Trader and correlation risk','Strategies can underperform, and many traders may experience losses simultaneously.')+card('EXECUTION','Liquidity and slippage','Orders may fill later or at less favorable prices than expected, or fail to execute.')+card('LEVERAGE','Liquidation risk','Where leverage is allowed, adverse moves can amplify losses and cause rapid liquidation.')+card('TECHNOLOGY','API and system interruptions','Authentication, software, connectivity or exchange outages can interrupt execution and risk actions.')+card('CUSTODY','Exchange and counterparty risk','Assets held at an exchange remain exposed to exchange operations, security and counterparty events.')+'''</div></div></section>
<section class="section section--mist"><div class="container section-split"><div class="reveal">'''+e('BEFORE YOU APPLY')+'''<h2>Transparency starts with the right questions.</h2><p class="body-copy" style="margin-top:24px">Potential participants should understand what access Revat receives, which exchange holds the assets, how profits and losses are calculated, and which contractual terms govern allocations.</p><p class="body-copy">Regulatory status, jurisdictional eligibility and service availability must also be verified before onboarding.</p>'''+button('Read frequently asked questions','faq.html','forest')+'''</div><div class="soft-panel reveal"><h3>Before participation, confirm:</h3><ul class="check-list"><li>The correct legal entity and regulatory disclosures</li><li>Eligibility in your country of residence</li><li>Applicable fees and profit calculations</li><li>Exchange subaccount and API permissions</li><li>Withdrawal and reallocation procedures</li><li>Full RMS behavior and risk acknowledgments</li></ul></div></div></section>
'''
pages['risk-management.html']=("Risk Management & Account Structure | Revat Fund","Learn about Revat's proposed trading-only exchange API permissions, investor-owned subaccounts, RMS intervention threshold and crypto trading risks.",risk)

about=inner('Opportunity should be shaped by ability, choice and discipline.','ABOUT REVAT FUND','We are developing an approach that brings assessed crypto trading talent and investor-selected capital into a more transparent, structured process.',button('Explore our model','how-it-works.html')+button('Contact Revat','apply.html','outline'),'About')
about+='''<section class="section section--white"><div class="container section-split"><div class="reveal">'''+e('OUR PURPOSE')+'''<h2>Connecting talent and capital through a considered process.</h2><p class="body-copy" style="margin-top:24px">Capable trading talent exists beyond large institutional desks. Investors, meanwhile, may seek clearer ways to review the people and strategies involved in trading their capital.</p><p class="body-copy">Revat is designed to bring discovery, verification, investor selection and monitoring into one connected model — with risk recognized at each step.</p></div><div class="dark-panel reveal">'''+e('OUR PRINCIPLES',True)+'''<h3 style="font-size:2rem;margin-bottom:17px">Talent. Capital. Discipline.</h3><p>Talent should be demonstrated. Capital should be allocated deliberately. Risk should be acknowledged, measured and addressed through defined processes.</p></div></div></section>
<section class="section section--mist"><div class="container grid-2"><div class="soft-panel reveal">'''+e('OUR VISION')+'''<h3>Broader opportunity through informed participation.</h3><p class="body-copy">To develop a digital asset trading ecosystem where proven ability can gain visibility and eligible investors can make clearer trader selection decisions.</p></div><div class="soft-panel reveal">'''+e('OUR MISSION')+'''<h3>Connect the right process to the right opportunity.</h3><p class="body-copy">To build a structured platform for crypto trader assessment, investor-led capital allocation, performance visibility and defined risk management.</p></div></div></section>
<section class="section section--white"><div class="container">'''+heading('WHAT GUIDES OUR DESIGN','A modern experience with serious underlying principles.')+'''<div class="grid-3">'''+card('01','Meaningful assessment','Trading ability is evaluated through evidence or a structured demo assessment, not marketing claims.')+card('02','Deliberate choice','Investor selection is part of the proposed allocation process.')+card('03','Risk awareness','Risk management is a necessary discipline, not a promise that losses cannot happen.')+'''</div></div></section>
<section class="section"><div class="container section-split"><div class="reveal">'''+e('DEVELOPMENT JOURNEY')+'''<h2>From a proof of concept to a broader platform vision.</h2><p class="body-copy" style="margin-top:24px">Revat's business draft describes an initial proof of concept. Its next priorities include completing operational definitions, validating supported exchange connections, finalizing risk and fee terms, and making onboarding appropriate for the jurisdictions served.</p><p class="notice">The proof of concept has not been independently audited for this website content and must not be represented as proof of future returns or scaled performance.</p></div><div class="numbered-stack reveal"><div class="numbered-card"><span class="n">01</span><div><h3>Model validation</h3><p>Clarify trading, account and assessment architecture.</p></div></div><div class="numbered-card"><span class="n">02</span><div><h3>Platform readiness</h3><p>Confirm permissions, dashboards and operational workflows.</p></div></div><div class="numbered-card"><span class="n">03</span><div><h3>Responsible availability</h3><p>Publish confirmed service information and jurisdictional eligibility.</p></div></div></div></div></section>
'''
pages['about.html']=("About Revat Fund | Talent, Capital, Discipline","Learn about Revat's mission to connect assessed crypto traders with investor-selected capital through structured assessment and risk-aware processes.",about)

faq_items=[
('investor','What is Revat Fund?','Revat is developing a platform where eligible investors select from assessed crypto traders and allocate through a proposed exchange-subaccount and risk management framework.'),
('investor','How much capital is proposed to start?','The business draft proposes a starting minimum of 10,000 USDT, allocating at least 1,000 USDT to each of a minimum of ten traders. These are proposed terms, not a live offer.'),
('investor','Do investors choose their own traders?','Under the intended model, investors select approved traders from available platform listings. Approval does not predict returns.'),
('investor','Where does capital remain?','In eligible exchange subaccounts owned by the investor at a supported exchange, not in a pooled Revat trading wallet. Exchange custody and trading risks remain.'),
('investor','Which exchanges are contemplated?','The business draft names Binance and Bybit, subject to exchange eligibility, supported account types, jurisdictions and final integration.'),
('investor','How does performance sharing work?','Indicative standard terms propose a 60% investor and 40% Revat share of eligible trading profits. Terms, calculations, costs and settlement are not final; losses are possible.'),
('investor','Can investors withdraw at any time?','Withdrawal and reallocation procedures, including handling of open positions and exchange restrictions, must be defined in final operating terms. No immediate-access promise is made.'),
('trader','Do I need an existing live track record?','No suitable live record is required for the proposed two-month demo assessment route. All applicants remain subject to approval.'),
('trader','Does passing assessment guarantee capital?','No. Approval creates eligibility for investor selection, not a guaranteed allocation or earnings.'),
('trader','How are traders paid?','The draft indicates trader compensation may be funded from Revat’s performance share, with preliminary percentages of approximately 20–25% of eligible generated profits and other terms possible at larger capital tiers.'),
('trader','What does the read-only API permit?','Read-only assessment access is intended to allow review of trading information without granting trading or withdrawal authority.'),
('risk','Does Revat guarantee profits?','No. Crypto trading can produce substantial losses, including loss of all allocated capital. No fixed yield or guaranteed return is offered.'),
('risk','Does the RMS guarantee losses stay under 10%?','No. The intended intervention target is for an individual trading subaccount, and execution conditions or system failures can produce losses beyond it.'),
('risk','Can Revat withdraw through the trading API?','The proposed setup requires trading-only API permissions with withdrawals disabled. Trading permissions still expose funds to trading risk.'),
('risk','Does investing across ten traders eliminate risk?','No. Strategies can move together, and correlated losses may occur across multiple trader allocations.'),
('risk','Is Revat available or regulated in my country?','Eligibility, legal entity details and regulatory status have not been confirmed in the supplied materials. They must be reviewed and published before live participation.'),
]
faq=inner('Important questions deserve clear answers.','FREQUENTLY ASKED QUESTIONS','Explore the proposed account structure, trader assessment, profit sharing and material risks before considering participation.',button('Submit an enquiry','apply.html'),'FAQs')
faq+='''<section class="section section--white"><div class="container" style="max-width:980px">'''+heading('EXPLORE THE DETAILS','Find the answers that matter to you.','Select a category or browse every question. These answers describe a proposed business model, not a finalized financial offer.')+'''<div class="faq-tabs"><button class="filter-chip active" data-filter="all" aria-pressed="true">All questions</button><button class="filter-chip" data-filter="investor" aria-pressed="false">Investors</button><button class="filter-chip" data-filter="trader" aria-pressed="false">Traders</button><button class="filter-chip" data-filter="risk" aria-pressed="false">Risk &amp; accounts</button></div><div class="faq-list">'''
